-- migration-policy: table-rebuild
-- B-227: approved 13 retained tables / 15 references. Internal history IDs have no FK.
-- Run the complete file in ONE transaction. Never apply statements as separate commits.
-- Each copy handles at most 1,000 rowids. Refuse rowids outside 1..100,000 before any DROP.
-- Actual staging counts/timings must be checked by HQ before application (no remote access here).
PRAGMA defer_foreign_keys = ON;

-- affiliate_payout_batch_lines
CREATE TABLE affiliate_payout_batch_lines_new (
  affiliate_id_history TEXT,
  id TEXT PRIMARY KEY,
  batch_id TEXT NOT NULL REFERENCES affiliate_payout_batches(id),
  settlement_line_id TEXT NOT NULL REFERENCES affiliate_settlement_lines(id),
  affiliate_id TEXT REFERENCES affiliates(id) ON DELETE SET NULL,
  amount_minor INTEGER NOT NULL,
  bank_code TEXT NOT NULL,
  bank_name TEXT NOT NULL,
  branch_code TEXT NOT NULL,
  branch_name TEXT NOT NULL,
  account_type TEXT NOT NULL CHECK (account_type IN ('ordinary', 'checking')),
  account_number_encrypted TEXT NOT NULL,
  account_last4 TEXT NOT NULL,
  account_holder_name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (batch_id, settlement_line_id)
);
SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM affiliate_payout_batch_lines WHERE rowid < 1 OR rowid > 100000) THEN 1 ELSE json('migration_634_rowid_limit_affiliate_payout_batch_lines') END;
SELECT CASE WHEN (SELECT COUNT(*) FROM affiliate_payout_batch_lines_new) = (SELECT COUNT(*) FROM affiliate_payout_batch_lines) THEN 1 ELSE json('migration_634_copy_count_affiliate_payout_batch_lines') END;
DROP TABLE affiliate_payout_batch_lines;
ALTER TABLE affiliate_payout_batch_lines_new RENAME TO affiliate_payout_batch_lines;
CREATE TRIGGER affiliate_payout_batch_lines_history_insert AFTER INSERT ON affiliate_payout_batch_lines BEGIN UPDATE affiliate_payout_batch_lines SET affiliate_id_history = COALESCE(NEW.affiliate_id, NEW.affiliate_id_history) WHERE id = NEW.id; END;
CREATE TRIGGER affiliate_payout_batch_lines_history_detach AFTER UPDATE OF affiliate_id ON affiliate_payout_batch_lines BEGIN UPDATE affiliate_payout_batch_lines SET affiliate_id_history = COALESCE(NEW.affiliate_id, OLD.affiliate_id, OLD.affiliate_id_history) WHERE id = NEW.id; END;

